            text = "|cFFFF3333当一花世界盛开\n我饰以色彩 睁开眼睛\n予它阳光雨露 我是谁\n予它热烈的新生\n何人赐我灵魂\n当一叶菩提凋零\n我愿为它引渡魂灵 不愿遗忘\n予它知晓归途 她与我\n予它羽翼升空\n彼岸花开新生\n跃起吧 生命在此起舞\n投身去 再不惧深海迷途\n我拨开了重影浓雾\n我抵达那百花深处\n萤火向你聚拢\n我已不再孤独\n林间歌声如风\n我也不再啼哭\n回望孩童时弱小的我\n我照看着坚强的她\n原来生命终得幸福\n原来我也终得幸福\n跃起吧 生命在此起舞\n投身去 再不惧深海迷途\n世界泡影不尽其数\n我终寻见百花深处\n千星向你聚拢\n我已不再孤独\n银河掌声雷动\n我也不再啼哭\n我倾听着白昼与黑夜\n我注视着潮汐流转\n祝愿生命终得幸福\n祝愿我也终得幸福\n跃起吧 生命在此起舞\n投身去 再不惧深海迷途\n我亲吻着指尖彩蝶\n我早已在百花深处\n有人伴你身旁\n不必感到孤独\n经历使人成长\n不必逃离痛楚\n我化身为蝶扇动翅膀\n我把微风吹向远方\n祝愿生命都能幸福\n祝愿你我都能幸福|r",
